css:
.pandemia-sim-container {
    padding: 24px;
    background: #0a0f1e;
    min-height: 100vh;
    font-family: 'Courier New', 'SF Mono', 'Consolas', monospace;
    color: #c9d1d9;
}

.pandemia-sim-header {
    border-left: 4px solid #ff4444;
    padding: 24px 28px;
    margin-bottom: 24px;
    background: rgba(255,68,68,0.06);
    position: relative;
}
.pandemia-sim-header-badge {
    display: inline-block;
    background: #ff4444;
    color: #0a0f1e;
    font-size: 0.65rem;
    font-weight: 700;
    letter-spacing: 0.15em;
    padding: 3px 10px;
    border-radius: 2px;
    margin-bottom: 10px;
}
.pandemia-sim-header h1 {
    color: #ff6b6b;
    font-size: 1.6rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    margin: 0 0 6px 0;
    text-shadow: 0 0 20px rgba(255,68,68,0.3);
}
.pandemia-sim-subtitle {
    color: #6b7b8d;
    font-size: 0.85rem;
    margin: 0;
    letter-spacing: 0.05em;
}

.pandemia-sim-period-counter {
    text-align: center;
    padding: 12px;
    margin-bottom: 24px;
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 6px;
    font-size: 0.95rem;
    color: #8b949e;
}
.pandemia-sim-period-counter #currentDay {
    color: #ff6b6b;
    font-weight: 700;
    font-size: 1.3rem;
}
.pandemia-sim-round-label {
    text-transform: uppercase;
    letter-spacing: 0.1em;
    font-size: 0.75rem;
}
.pandemia-sim-round-name {
    display: block;
    color: #58a6ff;
    font-size: 0.8rem;
    margin-top: 4px;
    letter-spacing: 0.06em;
}

.pandemia-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 14px;
    margin-bottom: 24px;
}
.pandemia-sim-kpi-card {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 18px 14px;
    position: relative;
    overflow: hidden;
    text-align: center;
}
.pandemia-sim-kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
}
.pandemia-kpi-cash::before { background: linear-gradient(90deg, #ff4444, #ff6b6b); }
.pandemia-kpi-employees::before { background: linear-gradient(90deg, #58a6ff, #79c0ff); }
.pandemia-kpi-burn::before { background: linear-gradient(90deg, #f0883e, #d29922); }
.pandemia-kpi-runway::before { background: linear-gradient(90deg, #ff4444, #da3633); }
.pandemia-kpi-hotels::before { background: linear-gradient(90deg, #3fb950, #56d364); }
.pandemia-kpi-occupancy::before { background: linear-gradient(90deg, #bc8cff, #d2a8ff); }

.pandemia-sim-kpi-label {
    color: #6b7b8d;
    font-size: 0.65rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    margin-bottom: 8px;
}
.pandemia-sim-kpi-value {
    font-size: 1.5rem;
    font-weight: 700;
    color: #e6edf3;
}
.pandemia-kpi-cash .pandemia-sim-kpi-value { color: #ff6b6b; }
.pandemia-kpi-runway .pandemia-sim-kpi-value { color: #da3633; }
.pandemia-kpi-burn .pandemia-sim-kpi-value { color: #f0883e; }
.pandemia-kpi-hotels .pandemia-sim-kpi-value { color: #3fb950; }

.pandemia-sim-briefing {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-left: 4px solid #58a6ff;
    border-radius: 8px;
    padding: 20px 24px;
    margin-bottom: 24px;
    line-height: 1.65;
}
.pandemia-sim-briefing-icon {
    font-size: 1.6rem;
    margin-bottom: 8px;
}
.pandemia-sim-briefing-title {
    color: #58a6ff;
    font-size: 0.9rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-bottom: 10px;
}
.pandemia-sim-briefing-text {
    color: #8b949e;
    font-size: 0.82rem;
    line-height: 1.7;
}

.pandemia-sim-controls {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 24px;
    margin-bottom: 24px;
}
.pandemia-sim-controls h3 {
    color: #c9d1d9;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-bottom: 18px;
    padding-bottom: 10px;
    border-bottom: 1px solid #1f2d3d;
}
.pandemia-sim-controls label {
    display: block;
    color: #8b949e;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-bottom: 6px;
    margin-top: 14px;
}
.pandemia-sim-select {
    width: 100%;
    background: #0a0f1e;
    border: 1px solid #2d3f55;
    color: #c9d1d9;
    border-radius: 4px;
    padding: 10px 14px;
    font-family: 'Courier New', monospace;
    font-size: 0.8rem;
    appearance: none;
    -webkit-appearance: none;
    cursor: pointer;
    transition: border-color 0.2s ease;
}
.pandemia-sim-select:focus {
    border-color: #58a6ff;
    outline: none;
    box-shadow: 0 0 0 2px rgba(88,166,255,0.15);
}
.pandemia-sim-select option {
    background: #0a0f1e;
    color: #c9d1d9;
}

.pandemia-sim-btn-row {
    display: flex;
    gap: 12px;
    margin-top: 20px;
}
.pandemia-sim-btn-submit {
    flex: 1;
    background: linear-gradient(135deg, #b91c1c, #dc2626);
    color: #ffffff;
    border: none;
    border-radius: 6px;
    padding: 12px 20px;
    font-family: 'Courier New', monospace;
    font-size: 0.85rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    cursor: pointer;
    transition: all 0.2s ease;
    box-shadow: 0 0 16px rgba(220,38,38,0.2);
}
.pandemia-sim-btn-submit:hover {
    background: linear-gradient(135deg, #dc2626, #ef4444);
    box-shadow: 0 0 24px rgba(220,38,38,0.4);
    transform: translateY(-1px);
}
.pandemia-sim-btn-undo {
    background: transparent;
    color: #6b7b8d;
    border: 1px solid #2d3f55;
    border-radius: 6px;
    padding: 12px 16px;
    font-family: 'Courier New', monospace;
    font-size: 0.78rem;
    cursor: pointer;
    transition: all 0.2s ease;
}
.pandemia-sim-btn-undo:hover {
    color: #c9d1d9;
    border-color: #58a6ff;
}

.pandemia-sim-chart-section {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
    margin-bottom: 24px;
}
.pandemia-sim-chart-box {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 16px;
    height: 260px;
}

.pandemia-sim-history {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 16px;
    overflow-x: auto;
}
.pandemia-sim-container .table {
    color: #c9d1d9;
    font-size: 0.78rem;
    margin: 0;
}
.pandemia-sim-container .table thead th {
    border-color: #2d3f55;
    color: #58a6ff;
    font-size: 0.68rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    font-weight: 600;
    padding: 10px 8px;
}
.pandemia-sim-container .table tbody td {
    border-color: #1f2d3d;
    padding: 8px;
    vertical-align: middle;
}
.pandemia-sim-container .table tbody tr:hover {
    background: rgba(88,166,255,0.04);
}

@media (max-width: 768px) {
    .pandemia-sim-container { padding: 14px; }
    .pandemia-sim-kpi-grid { grid-template-columns: repeat(2, 1fr); gap: 10px; }
    .pandemia-sim-chart-section { grid-template-columns: 1fr; }
    .pandemia-sim-kpi-value { font-size: 1.2rem; }
    .pandemia-sim-btn-row { flex-direction: column; }
    .pandemia-sim-header h1 { font-size: 1.2rem; }
}

