        getPerformanceSummary(history) {
            if (!history.length) return {};
            var lastRecord = history[history.length - 1];
            var finalCash = lastRecord.results ? lastRecord.results.cash : 0;
            var finalRunway = lastRecord.results ? lastRecord.results.runwayWeeks : 0;
            var finalEmployees = lastRecord.results ? lastRecord.results.employees : 0;

            var perfKey = 'perf_dead';
            var insights = [];

            if (finalCash > 3000000 && finalRunway > 52) {
                perfKey = 'perf_excellent';
                insights.push(this._t('insight_excellent'));
            } else if (finalCash > 1000000 && finalRunway > 26) {
                perfKey = 'perf_solid';
                insights.push(this._t('insight_solid'));
            } else if (finalCash > 0 && finalRunway > 12) {
                perfKey = 'perf_fragile';
                insights.push(this._t('insight_fragile'));
            } else {
                insights.push(this._t('insight_dead'));
            }

            if (finalEmployees > 200) {
                insights.push(this._t('insight_high_retention'));
            } else if (finalEmployees < 100) {
                insights.push(this._t('insight_low_retention'));
            }

            return {
                finalCash: finalCash,
                runwayWeeks: finalRunway,
                employees: finalEmployees,
                performance: this._t(perfKey),
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.runwayWeeks < 8) {
                return window.mySimulation.t('hint_critical_runway');
            }
            if (results.cash < 500000) {
                return window.mySimulation.t('hint_low_cash');
            }
            if (state.currentPeriod === 1 && results.cashImpact < -1500000) {
                return window.mySimulation.t('hint_high_severance');
            }
            if (state.currentPeriod === 3 && results.hotelsOpen === 0) {
                return window.mySimulation.t('hint_closure_risk');
            }
            return null;
        }

